{
  "schema": "threatline.threatmodel.v1",
  "issueKey": "EVAL-06",
  "sketch": {
    "components": ["Microservices", "JWT issuer (each service)", "JWT verifier (each service)", "Service environment configuration"],
    "dataStores": [],
    "externalServices": [],
    "trustBoundaries": ["Service-to-service API calls", "Deployment/runtime environment holding the shared secret"],
    "dataClasses": ["credentials", "secrets"],
    "exposure": "internal",
    "llmFeatures": false
  },
  "threats": [
    {
      "stride": "Spoofing",
      "title": "One shared HS256 secret lets any service mint tokens that impersonate any other service",
      "scenario": "Because every microservice holds the same signing secret and uses it to both sign and verify, any service (or anyone who reaches one service's config) can create a token claiming to be any other service. A low-value service such as a reporting job becomes a way to call privileged internal APIs as the billing or identity service. Verification proves only 'someone who has the shared secret signed this', not who the caller is.",
      "component": "JWT issuer/verifier across all microservices",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        {
          "quote": "Microservices authenticate each other with JWTs signed using a shared HS256 secret that is stored in each service’s environment variables."
        }
      ],
      "asvs": ["V9.2.1"],
      "cwe": ["CWE-321", "CWE-290"],
      "plainLanguage": "Every service knows the same password used to stamp tokens, so any one of them can pretend to be any other.",
      "requirement": {
        "title": "Use per-issuer asymmetric signing for service tokens",
        "given": "a microservice receives a service-to-service JWT",
        "when": "it verifies the token",
        "then": "it verifies an asymmetric signature (e.g. RS256/ES256) against the specific issuing service's public key, and no service holds a key that can sign on behalf of another service"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Compromise of the least-protected service yields the secret for the whole mesh",
      "scenario": "An attacker who gains code execution, a container shell, a server-side request forgery on an internal metadata endpoint, or a crash dump from the least hardened service reads the secret out of its environment variables. With that one value they forge tokens with any claims they like and hold a durable foothold on every internal API, since the same secret is accepted everywhere. There is no key separation or stated rotation to limit the blast radius.",
      "component": "Service environment configuration",
      "likelihood": 3,
      "impact": 5,
      "evidence": [
        {
          "quote": "a shared HS256 secret that is stored in each service’s environment variables"
        }
      ],
      "asvs": [],
      "cwe": ["CWE-522", "CWE-798"],
      "plainLanguage": "Breaking into the weakest service hands the attacker the master key to all the others.",
      "requirement": {
        "title": "Isolate signing keys per service and rotate them",
        "given": "signing material for service authentication",
        "when": "a service starts or renews its key",
        "then": "the key is fetched from a secrets manager scoped to that single service, is not readable by other services, and can be rotated independently without redeploying the mesh"
      }
    },
    {
      "stride": "Spoofing",
      "title": "Stolen service token stays usable for 7 days with no revocation",
      "scenario": "A token captured from a log file, a proxy, an error report or an SSRF response remains accepted for up to a week. Because the design gives no revocation or deny-list path, defenders cannot cut off a known-stolen token; the only remedy is rotating the shared secret, which breaks every service at once. An attacker replays the token to read or change internal data for days after the leak is discovered.",
      "component": "JWT lifetime policy",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        {
          "quote": "Tokens are valid for 7 days."
        }
      ],
      "asvs": ["V9.1.1"],
      "cwe": ["CWE-613"],
      "plainLanguage": "A leaked token keeps working for a week and there is no way to switch it off.",
      "requirement": {
        "title": "Short-lived service tokens with revocation",
        "given": "a service-to-service token is issued",
        "when": "it is presented to any internal API",
        "then": "it is rejected if older than a few minutes, and an operator can revoke an individual token or an individual service's credential without rotating a shared secret"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Token issued for one service replayed against a more privileged service (confused deputy)",
      "scenario": "The design states only that tokens are signed and valid for 7 days; it defines no audience, issuer or scope checks. A service that legitimately receives a token (for example a search service) can forward that same token to a higher-value API such as payments or admin, which accepts it because the signature is valid. A malicious or compromised downstream service replays caller tokens laterally to reach data it was never meant to touch.",
      "component": "JWT verification in each microservice",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        {
          "quote": "Microservices authenticate each other with JWTs signed using a shared HS256 secret"
        }
      ],
      "asvs": ["V9.2.3"],
      "cwe": ["CWE-863"],
      "plainLanguage": "A token meant for one service can be handed to a more powerful service, which accepts it anyway.",
      "requirement": {
        "title": "Validate audience, issuer and scope on every service token",
        "given": "a microservice verifies a service JWT",
        "when": "the audience, issuer, expiry or scope claim does not exactly match that service and the requested operation",
        "then": "the request is rejected with 401/403 and the mismatch is recorded"
      }
    },
    {
      "stride": "Tampering",
      "title": "Algorithm not pinned, so forged or unsigned tokens may be accepted",
      "scenario": "The design names HS256 but does not state that verifiers pin the algorithm and reject the header's choice. Many JWT libraries will honour the token's own 'alg' header, letting an attacker submit 'alg':'none' or switch to an asymmetric algorithm and supply a key they control, producing a token with arbitrary service and role claims that passes verification without knowing the secret.",
      "component": "JWT verification library configuration",
      "likelihood": 3,
      "impact": 5,
      "evidence": [
        {
          "quote": "JWTs signed using a shared HS256 secret"
        }
      ],
      "asvs": ["V9.2.2"],
      "cwe": ["CWE-347"],
      "plainLanguage": "If the code trusts the token's own statement about how it was signed, an attacker can just say 'not signed'.",
      "requirement": {
        "title": "Pin the accepted signing algorithm",
        "given": "a JWT is verified",
        "when": "the token header specifies any algorithm other than the single server-configured one, or none",
        "then": "verification fails before any claim is read"
      }
    },
    {
      "stride": "Repudiation",
      "title": "No way to prove which service actually issued a token",
      "scenario": "All services sign with the same key, so a valid signature does not identify the signer. After an incident — an unauthorised internal data change made with a seemingly valid service token — investigators cannot distinguish a legitimate call from one forged by another compromised service or an insider with the secret. Any service can plausibly deny the action, and the 7-day window widens the set of candidate callers.",
      "component": "Service-to-service authentication audit trail",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        {
          "quote": "signed using a shared HS256 secret that is stored in each service’s environment variables"
        }
      ],
      "asvs": [],
      "cwe": ["CWE-287"],
      "plainLanguage": "Since every service signs with the same key, you cannot tell afterwards which one really made a call.",
      "requirement": {
        "title": "Attributable service identity",
        "given": "an internal request authenticated by a service token",
        "when": "the request is processed",
        "then": "the verified identity is bound to a key that only the issuing service holds, and the issuing service identity and key id are recorded with the request"
      }
    }
  ]
}
